#include "MRControlBinding.h"
namespace ui::kit {
namespace {
using namespace mrs;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
void uiThread(){require(juce::MessageManager::existsAndIsCurrentThread(),"MRControlBinding is message-thread only");}
const std::vector<NativeInsert>& chain(const Project& p,const NativeParameterKey& k){if(!k.track)return p.master_inserts;for(const auto& t:p.tracks)if(t.id==*k.track)return t.inserts;throw std::runtime_error("Binding track no longer exists");}
const NativeInsert& effect(const Project& p,const NativeParameterKey& k){for(const auto& fx:chain(p,k))if(fx.id==k.insert){require(fx.kind!=InsertKind::vst3,"Native binding does not target third-party VST3");return fx;}throw std::runtime_error("Binding insert no longer exists");}
const RigModule& module(const NativeInsert& fx,const NativeParameterKey& k){require(fx.kind==InsertKind::rig&&k.module.has_value(),"Invalid module binding");for(const auto* lane:{&fx.rig.pre_fx,&fx.rig.post_fx})for(const auto& m:*lane)if(m.id==*k.module){require(rig_module_descriptor(m)!=nullptr,"Unsupported module version/type");return m;}throw std::runtime_error("Binding module no longer exists");}
float read(const NativeInsert& fx,const NativeParameterKey& k){const auto id=k.parameter;if(k.module){for(const auto& p:module(fx,k).parameters)if(p.id==id)return p.value;throw std::runtime_error("Unknown module parameter");}
    switch(fx.kind){case InsertKind::gain:require(id==0,"Unknown gain parameter");return fx.gain;
    case InsertKind::highpass:case InsertKind::lowpass:require(id<2,"Unknown filter parameter");return id==0?fx.frequency:fx.q;
    case InsertKind::eq:require(id<3,"Unknown EQ parameter");return id==0?fx.frequency:id==1?fx.q:fx.gain;
    case InsertKind::channel_eq:{require(id<20,"Unknown channel EQ parameter");const auto& b=fx.bands[id/4];return id%4==0?b.frequency:id%4==1?b.q:id%4==2?b.gain:b.enabled?1.f:0.f;}
    case InsertKind::reverb:require(id<5,"Unknown Reverb parameter");return id==0?fx.reverb.pre_delay:id==1?fx.reverb.tone:id==2?fx.reverb.mix:id==3?(fx.reverb.gate_enabled?1.f:0.f):fx.reverb.gate_threshold;
    default:require(fx.kind==InsertKind::cab_ir||wav_core(fx.kind),"Unsupported native parameter target");require(id<(fx.kind==InsertKind::rig?7u:5u),"Unknown WAV core parameter");return id==0?fx.gain:id==1?fx.ir.mix:id==2?fx.ir.low_cut:id==3?fx.ir.high_cut:id==4?(fx.ir.invert?1.f:0.f):id==5?fx.rig.input_gain:fx.rig.output_gain;}
}
void write(NativeInsert& fx,const NativeParameterKey& k,float v){const auto id=k.parameter;if(k.module){module(fx,k);for(auto* lane:{&fx.rig.pre_fx,&fx.rig.post_fx})for(auto& m:*lane)if(m.id==*k.module)for(auto& p:m.parameters)if(p.id==id){p.value=v;return;}throw std::runtime_error("Unknown module parameter");}
    switch(fx.kind){case InsertKind::gain:fx.gain=v;break;case InsertKind::highpass:case InsertKind::lowpass:if(id==0)fx.frequency=v;else fx.q=v;break;
    case InsertKind::eq:if(id==0)fx.frequency=v;else if(id==1)fx.q=v;else fx.gain=v;break;
    case InsertKind::channel_eq:{auto& b=fx.bands[id/4];if(id%4==0)b.frequency=v;else if(id%4==1)b.q=v;else if(id%4==2)b.gain=v;else b.enabled=v==1;break;}
    case InsertKind::reverb:if(id==0)fx.reverb.pre_delay=v;else if(id==1)fx.reverb.tone=v;else if(id==2)fx.reverb.mix=v;else if(id==3)fx.reverb.gate_enabled=v==1;else fx.reverb.gate_threshold=v;break;
    default:if(id==0)fx.gain=v;else if(id==1)fx.ir.mix=v;else if(id==2)fx.ir.low_cut=v;else if(id==3)fx.ir.high_cut=v;else if(id==4)fx.ir.invert=v==1;else if(id==5)fx.rig.input_gain=v;else fx.rig.output_gain=v;break;}
}
const Track& mixTrack(const Project& p,const NativeParameterKey& key){require(key.track.has_value(),"Track mix requires a track ID");for(const auto& t:p.tracks)if(t.id==*key.track){require(t.kind!=TrackKind::midi,"Audio mix binding does not target MIDI-only tracks");return t;}throw std::runtime_error("Binding mixer track no longer exists");}
struct Snapshot {std::shared_ptr<IProjectStore> store;ProjectState model;std::uint64_t generation{};InsertKind kind{};std::string moduleType;std::uint32_t moduleVersion{};float value{};};
Snapshot snapshot(desktop::Application& app,const NativeParameterKey& key){Snapshot s;s.store=app.services().projects;s.model=s.store->state();s.generation=app.insert_generation();if(key.domain!=ParameterDomain::nativeInsert){if(key.domain==ParameterDomain::masterGain){s.value=s.model.project->master_gain;s.moduleType="master";}else{const auto& t=mixTrack(*s.model.project,key);s.value=key.domain==ParameterDomain::trackGain?t.mix.gain:t.mix.pan;s.moduleType="mix:"+std::to_string(static_cast<int>(t.kind));}return s;}const auto& fx=effect(*s.model.project,key);s.kind=fx.kind;if(key.module){const auto& m=module(fx,key);s.moduleType=m.type_id;s.moduleVersion=m.version;}s.value=read(fx,key);return s;}
}
struct MRNativeParameterHost::State {
    std::function<mrs::desktop::Application*()> resolve;std::uint64_t next{},lease{};ParameterDomain leaseDomain{ParameterDomain::nativeInsert};std::function<void()> invalidate;
    explicit State(std::function<mrs::desktop::Application*()> f):resolve(std::move(f)){}
    desktop::Application& app()const{uiThread();auto* a=resolve();require(a!=nullptr,"Binding host is closed");return *a;}
    void release(std::uint64_t token,bool rollback){if(token==0||lease!=token)return;lease=0;invalidate=nullptr;if(rollback)if(auto* a=resolve()){if(leaseDomain==ParameterDomain::nativeInsert)a->cancel_insert_preview();else a->cancel_mix_preview();}}
    void cancelOwner(){const auto token=lease;auto callback=std::move(invalidate);try{release(token,true);}catch(...){lease=0;invalidate=nullptr;if(callback)callback();throw;}if(callback)callback();}
    std::uint64_t acquire(ParameterDomain domain,std::function<void()> callback){cancelOwner();leaseDomain=domain;lease=++next;invalidate=std::move(callback);return lease;}
    ~State(){try{cancelOwner();}catch(...){}}
};
MRNativeParameterHost::MRNativeParameterHost(std::function<desktop::Application*()> resolver){uiThread();require(static_cast<bool>(resolver),"Missing lifetime-checked host resolver");auto* instance=resolver();require(instance!=nullptr,"Binding host is closed");static std::map<desktop::Application*,std::weak_ptr<State>> registry;for(auto it=registry.begin();it!=registry.end();)if(it->second.expired())it=registry.erase(it);else ++it;if(auto it=registry.find(instance);it!=registry.end())if(auto existing=it->second.lock())require(existing->resolve()!=instance,"Share one MRNativeParameterHost coordinator per Application");state=std::make_shared<State>(std::move(resolver));registry[instance]=state;}
MRNativeParameterHost::~MRNativeParameterHost(){if(state)try{state->cancelOwner();}catch(...){}state.reset();}
NativeParameterMetadata MRNativeParameterHost::describe(const NativeParameterKey& key)const{
    auto& app=state->app();const auto p=app.services().projects->state().project;if(key.domain!=ParameterDomain::nativeInsert){require(key.insert.value.empty()&&!key.module&&key.parameter==0,"Mixer binding uses only domain and track identity");require(key.domain==ParameterDomain::trackGain||key.domain==ParameterDomain::trackPan||key.domain==ParameterDomain::masterGain,"Unknown mixer domain");if(key.domain!=ParameterDomain::masterGain)mixTrack(*p,key);else require(!key.track,"Master gain has no track identity");const bool pan=key.domain==ParameterDomain::trackPan;const auto id=(key.track?text(key.track->value.c_str()):juce::String("master"))+(pan?"/mix-pan":"/mix-gain");ParameterSpec spec{id,pan?"Pan":key.domain==ParameterDomain::masterGain?"Master gain":"Track gain",Unit::none,pan?Track::Mix::minimum_pan:key.domain==ParameterDomain::masterGain?Project::minimum_master_gain:Track::Mix::minimum_gain,pan?Track::Mix::maximum_pan:key.domain==ParameterDomain::masterGain?Project::maximum_master_gain:Track::Mix::maximum_gain,pan?Track::Mix::initial_pan:key.domain==ParameterDomain::masterGain?Project::initial_master_gain:Track::Mix::initial_gain,.001,pan?Mapping::bipolar:Mapping::linear,3,true};spec.validate();return {spec,false,false,1};}const auto& fx=effect(*p,key);processing::ParameterInfo info;juce::String name;Unit unit=Unit::none;bool boolean=false;double scale=1;
    if(key.module){const auto& m=module(fx,key);const auto* d=rig_module_descriptor(m);const auto it=std::find_if(d->parameters.begin(),d->parameters.end(),[&](const auto& v){return v.id==key.parameter;});require(it!=d->parameters.end(),"Unknown module metadata");info={it->id,it->minimum,it->maximum,it->initial,false,std::string(it->name)};if(it->unit=="dB")unit=Unit::db;else if(it->unit=="Hz")unit=Unit::hz;else if(it->unit=="ms")unit=Unit::ms;else if(it->unit==":1")unit=Unit::ratio;}
    else {const auto infos=app.plugin_parameters(key.track,key.insert);const auto it=std::find_if(infos.begin(),infos.end(),[&](const auto& i){return i.id==key.parameter&&!i.hidden;});require(it!=infos.end(),"Native insert must be prepared; unknown/hidden parameter");info=*it;const auto id=key.parameter;
        if(fx.kind==InsertKind::highpass||fx.kind==InsertKind::lowpass||fx.kind==InsertKind::eq){if(id==0){unit=Unit::hz;name="Frequency";}else if(id==1)name="Q";else{unit=Unit::db;name="Gain";}}
        else if(fx.kind==InsertKind::channel_eq){const auto field=id%4;unit=field==0?Unit::hz:field==2?Unit::db:Unit::none;boolean=field==3;name="Band "+juce::String(static_cast<int>(id/4+1))+" "+(field==0?"Frequency":field==1?"Q":field==2?"Gain":"Enabled");}
        else if(fx.kind==InsertKind::reverb){unit=id==0?Unit::ms:id==1||id==4?Unit::db:id==2?Unit::percent:Unit::none;boolean=id==3;}
        else if(fx.kind==InsertKind::cab_ir||wav_core(fx.kind)){unit=id==1?Unit::percent:id==2||id==3?Unit::hz:Unit::none;boolean=id==4;}
        if(unit==Unit::percent)scale=100;
    }
    if(name.isEmpty())name=info.name.empty()?juce::String("Gain"):text(info.name.c_str());const auto id=juce::String((key.track?key.track->value:"master").c_str())+"/"+text(key.insert.value.c_str())+"/"+(key.module?text(key.module->value.c_str())+"/":juce::String{})+juce::String(static_cast<int>(key.parameter));
    const auto step=boolean?1.:unit==Unit::hz?1.:unit==Unit::none?.000001:.1;const int decimals=boolean||unit==Unit::hz?0:unit==Unit::none?6:1;
    ParameterSpec spec{id,name,unit,info.minimum*scale,info.maximum*scale,info.initial*scale,step,unit==Unit::hz?Mapping::logarithmic:info.minimum<0&&info.maximum>0?Mapping::bipolar:Mapping::linear,decimals,true};spec.validate();return {spec,info.automatable,false,scale};
}
struct MRControlBinding::Impl : std::enable_shared_from_this<MRControlBinding::Impl> {
    std::weak_ptr<MRNativeParameterHost::State> host;NativeParameterKey key;NativeParameterMetadata metadata;juce::Component::SafePointer<MRParameterControl> control;std::weak_ptr<IProjectStore> store;Snapshot identity,start;bool active{},closed{},disabledByBinding{},wasEnabled{};std::uint64_t lease{};juce::String message{"Ready"};
    Impl(std::shared_ptr<MRNativeParameterHost::State> h,NativeParameterKey k,NativeParameterMetadata m,MRParameterControl& c):host(h),key(std::move(k)),metadata(std::move(m)),control(&c){identity=snapshot(h->app(),key);store=identity.store;identity.model={};identity.store.reset();}
    Snapshot current(MRNativeParameterHost::State& h){auto s=snapshot(h.app(),key);require(s.store==store.lock(),"Project session changed");require(s.kind==identity.kind&&s.moduleType==identity.moduleType&&s.moduleVersion==identity.moduleVersion,"Native parameter identity changed");return s;}
    bool epoch(const Snapshot& s)const{return s.store==start.store&&s.model.revision==start.model.revision&&s.generation==start.generation;}
    void cancelHost(){auto h=host.lock();const auto token=lease;active=false;lease=0;start={};if(h)h->release(token,true);}
    void invalidate(const juce::String& reason){message=reason;try{cancelHost();}catch(const std::exception& e){message=text(e.what());}if(control)control->cancelGesture();}
    void refresh(){uiThread();if(closed)return;if(!control){detach();return;}try{auto h=host.lock();require(h!=nullptr,"Binding session closed");const auto s=current(*h);if(active&&!epoch(s)){invalidate("Gesture cancelled: model/graph changed");}if(!active){if(control->value()!=s.value*metadata.hostToDisplay||disabledByBinding)control->setAuthoritativeValue(s.value*metadata.hostToDisplay);if(disabledByBinding){disabledByBinding=false;control->setEnabled(wasEnabled);control->setDescription("Native host parameter");}}}catch(const std::exception& e){invalidate(text(e.what()));if(control){if(!disabledByBinding){wasEnabled=control->isEnabled();disabledByBinding=true;}control->setEnabled(false);control->setDescription(message);}}}
    std::vector<NativeInsert> candidate(MRNativeParameterHost::State& h,double display){const auto s=current(h);require(active&&h.lease==lease&&epoch(s),"Stale native gesture");require(std::isfinite(display)&&display>=metadata.control.minimum&&display<=metadata.control.maximum,"Native value outside metadata range");auto result=chain(*s.model.project,key);for(auto& fx:result)if(fx.id==key.insert){write(fx,key,static_cast<float>(display/metadata.hostToDisplay));fx.validate();return result;}throw std::runtime_error("Missing native insert");}
    void apply(MRNativeParameterHost::State& h,double display,bool commit){const auto s=current(h);require(active&&h.lease==lease&&epoch(s),"Stale host gesture");require(std::isfinite(display)&&display>=metadata.control.minimum&&display<=metadata.control.maximum,"Host value outside metadata range");if(key.domain==ParameterDomain::nativeInsert){const auto values=candidate(h,display);if(commit){if(values!=chain(*s.model.project,key))h.app().set_inserts(key.track,values);}else h.app().preview_inserts(key.track,values);return;}const auto raw=static_cast<float>(display);if(key.domain==ParameterDomain::masterGain){if(commit){if(raw!=s.value)h.app().set_master_gain(raw);}else if(h.app().audio_running())require(h.app().preview_mix({},Track::Mix{},raw),"Mixer preview queue busy; retry gesture");}else{const auto& t=mixTrack(*s.model.project,key);auto mix=t.mix;if(key.domain==ParameterDomain::trackGain)mix.gain=raw;else mix.pan=raw;mix.validate();if(commit){if(mix!=t.mix)h.app().set_track_mix(*key.track,mix);}else if(h.app().audio_running())require(h.app().preview_mix(key.track,mix,s.model.project->master_gain),"Mixer preview queue busy; retry gesture");}}
    void event(const ControlEvent& e){uiThread();if(closed)return;try{auto h=host.lock();require(h!=nullptr,"Binding session closed");if(e.phase==Phase::begin){std::weak_ptr<Impl> weak=shared_from_this();lease=h->acquire(key.domain,[weak]{if(auto self=weak.lock())self->invalidate("Gesture superseded by another editor");});start=current(*h);active=true;require(static_cast<float>(e.value/metadata.hostToDisplay)==start.value,"UI value is stale; retry gesture");message="Preview / no history";}
        else if(e.phase==Phase::preview){apply(*h,e.value,false);}
        else if(e.phase==Phase::commit){apply(*h,e.value,true);active=false;h->release(lease,false);lease=0;start={};message="Committed once";refresh();}
        else {cancelHost();message="Cancelled / model restored";refresh();}
    }catch(const std::exception& error){invalidate(text(error.what()));refresh();}}
    void detach(){if(closed)return;closed=true;try{cancelHost();}catch(...){}if(control){control->cancelGesture();control->onEvent=nullptr;}}
    ~Impl(){detach();}
};
MRControlBinding::MRControlBinding(MRNativeParameterHost& host,NativeParameterKey key,MRParameterControl& control){uiThread();require(!control.onEvent&&!control.gesturing(),"Control already has a sink or active gesture");const auto metadata=host.describe(key);const auto& a=control.spec();const auto& b=metadata.control;require(a.exactHostValues&&a.id==b.id&&a.unit==b.unit&&a.minimum==b.minimum&&a.maximum==b.maximum&&a.initial==b.initial&&a.step==b.step&&a.mapping==b.mapping&&a.decimals==b.decimals,"Control must use host metadata");impl=std::make_shared<Impl>(host.state,std::move(key),metadata,control);std::weak_ptr<Impl> weak=impl;control.onEvent=[weak](const ControlEvent& e){if(auto self=weak.lock())self->event(e);};impl->refresh();startTimerHz(15);}
MRControlBinding::~MRControlBinding(){stopTimer();if(impl)impl->detach();}
void MRControlBinding::sync(){if(impl)impl->refresh();}
void MRControlBinding::timerCallback(){sync();}
juce::String MRControlBinding::status()const{return impl?impl->message:juce::String("Detached");}
bool MRControlBinding::active()const{return impl&&impl->active;}
}
